require_once __DIR__.'/../includes/auth.php';require_parent();$db=db();$parent=parent_user();$parentId=(int)$parent['id'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['link_code'])){$code=strtoupper(preg_replace('/[^A-Z0-9]/i','',(string)$_POST['link_code']));if(strlen($code)!==8)$error='Enter the complete 8-character code shown on the student account.';else{$db->begin_transaction();try{$student=query_one('SELECT u.id,u.full_name,g.grade_number FROM student_parent_codes c JOIN users u ON u.id=c.student_id JOIN grades g ON g.id=u.grade_id WHERE c.link_code=? AND c.expires_at>NOW() AND u.status="active" FOR UPDATE','s',[$code]);if(!$student)throw new RuntimeException('That code is invalid, expired, or has already been used.');$sid=(int)$student['id'];$existing=query_one('SELECT 1 linked FROM parent_student_links WHERE parent_id=? AND student_id=?','ii',[$parentId,$sid]);if(!$existing){$s=$db->prepare('INSERT INTO parent_student_links(parent_id,student_id) VALUES(?,?)');if(!$s)throw new RuntimeException('The link could not be prepared.');$s->bind_param('ii',$parentId,$sid);if(!$s->execute()||$s->affected_rows!==1)throw new RuntimeException('The parent-child link could not be saved.');}$s=$db->prepare('DELETE FROM student_parent_codes WHERE student_id=? AND link_code=?');$s->bind_param('is',$sid,$code);if(!$s->execute())throw new RuntimeException('The one-time code could not be completed.');$db->commit();flash('success','Grade '.(int)$student['grade_number'].' student '.(string)$student['full_name'].' linked successfully.');redirect('parent/dashboard.php?child='.$sid);}catch(Throwable $e){$db->rollback();$error=$e->getMessage();error_log('Parent link failed for parent '.$parentId.': '.$e->getMessage());}}}if(isset($_POST['mark_read'])){$sid=(int)$_POST['mark_read'];$s=$db->prepare('UPDATE parent_student_links SET last_seen_at=NOW() WHERE parent_id=? AND student_id=?');$s->bind_param('ii',$parentId,$sid);$s->execute();redirect('parent/dashboard.php?child='.$sid);}}
$s=$db->prepare('SELECT u.id,u.full_name,u.username,u.medium,g.grade_number,psl.linked_at,psl.last_seen_at FROM parent_student_links psl JOIN users u ON u.id=psl.student_id JOIN grades g ON g.id=u.grade_id WHERE psl.parent_id=? AND u.status="active" ORDER BY u.full_name');$s->bind_param('i',$parentId);$s->execute();$children=$s->get_result()->fetch_all(MYSQLI_ASSOC);
$requested=filter_input(INPUT_GET,'child',FILTER_VALIDATE_INT);$child=null;foreach($children as $c)if(!$requested||$requested===(int)$c['id']){$child=$c;break;}
$data=null;$searches=[];$lessons=[];$quizzes=[];$leaderboard=[];$leaderRank=0;$gradeStudents=0;$unread=0;
if($child){$sid=(int)$child['id'];$medium=$child['medium'];
 $overall=query_one("SELECT COUNT(DISTINCT l.id) total,COUNT(DISTINCT CASE WHEN lp.completed_at IS NOT NULL THEN l.id END) completed FROM lessons l LEFT JOIN lesson_progress lp ON lp.lesson_id=l.id AND lp.user_id=? WHERE l.grade_id=(SELECT grade_id FROM users WHERE id=?) AND l.content_source='textbook' AND l.status='active' AND (l.medium='All' OR l.medium=?)",'iis',[$sid,$sid,$medium])??['total'=>0,'completed'=>0];
 $points=(int)(query_one('SELECT COALESCE(SUM(points),0) n FROM student_points WHERE user_id=?','i',[$sid])['n']??0);$emblems=(int)(query_one('SELECT COUNT(*) n FROM student_emblems WHERE user_id=?','i',[$sid])['n']??0);$avg=(int)(query_one('SELECT COALESCE(ROUND(AVG(best_score)),0) n FROM (SELECT MAX(percentage) best_score FROM quiz_attempts WHERE user_id=? GROUP BY quiz_id) x','i',[$sid])['n']??0);$data=['total'=>(int)$overall['total'],'completed'=>(int)$overall['completed'],'points'=>$points,'emblems'=>$emblems,'average'=>$avg];
 $s=$db->prepare("SELECT cm.message,cm.created_at,s.name_en subject,l.title_en lesson FROM chat_messages cm LEFT JOIN subjects s ON s.id=cm.subject_id LEFT JOIN lessons l ON l.id=cm.lesson_id WHERE cm.user_id=? AND cm.role='user' ORDER BY cm.created_at DESC LIMIT 20");$s->bind_param('i',$sid);$s->execute();$searches=$s->get_result()->fetch_all(MYSQLI_ASSOC);
 $s=$db->prepare('SELECT l.title_en,s.name_en subject,lp.opened_at,lp.last_opened_at,lp.completed_at FROM lesson_progress lp JOIN lessons l ON l.id=lp.lesson_id JOIN subjects s ON s.id=l.subject_id WHERE lp.user_id=? ORDER BY lp.last_opened_at DESC LIMIT 20');$s->bind_param('i',$sid);$s->execute();$lessons=$s->get_result()->fetch_all(MYSQLI_ASSOC);
 $s=$db->prepare('SELECT q.title_en,qa.percentage,qa.passed,qa.completed_at FROM quiz_attempts qa JOIN quizzes q ON q.id=qa.quiz_id WHERE qa.user_id=? ORDER BY qa.completed_at DESC LIMIT 20');$s->bind_param('i',$sid);$s->execute();$quizzes=$s->get_result()->fetch_all(MYSQLI_ASSOC);
 $gradeId=(int)query_one('SELECT grade_id FROM users WHERE id=?','i',[$sid])['grade_id'];$s=$db->prepare("SELECT u.id,u.full_name,u.username,COALESCE(SUM(sp.points),0) points,COUNT(DISTINCT CASE WHEN sp.activity_type='lesson_complete' THEN sp.lesson_id END) completed FROM users u LEFT JOIN student_points sp ON sp.user_id=u.id WHERE u.grade_id=? AND u.status='active' GROUP BY u.id ORDER BY points DESC,completed DESC,u.id LIMIT 100");$s->bind_param('i',$gradeId);$s->execute();$allLeaders=$s->get_result()->fetch_all(MYSQLI_ASSOC);$gradeStudents=count($allLeaders);foreach($allLeaders as $i=>$leader){if((int)$leader['id']===$sid)$leaderRank=$i+1;if($i<5)$leaderboard[]=$leader;}
 $since=$child['last_seen_at']?:$child['linked_at'];$unread=(int)(query_one('SELECT COUNT(*) n FROM student_activity_events WHERE user_id=? AND event_time>?','is',[$sid,$since])['n']??0);
}
