ize:1.35rem;font-weight:900}.mini-leader{display:grid;grid-template-columns:42px 1fr auto;gap:10px;align-items:center;padding:12px 22px;border-bottom:1px solid #edf0f6}.mini-leader.current{background:#f2f0ff}.mini-leader b,.mini-leader small{display:block}.mini-leader small{color:var(--muted)}.mini-points{color:#5141c2;font-weight:900}.monitor-grid .card{max-height:520px;overflow:auto}.notification-card{background:linear-gradient(135deg,#fff,#f4f8ff)}@media(max-width:800px){.parent-hero{padding:23px}.parent-actions{width:100%;justify-content:space-between}.parent-metrics{grid-template-columns:1fr 1fr}.overview-progress{grid-template-columns:1fr}.monitor-grid .card{max-height:none}}@media(max-width:430px){.parent-hero{border-radius:23px}.live-pill{font-size:.68rem}.logout-btn{min-height:41px;padding:8px 12px}.parent-metrics{gap:8px}.parent-metrics .metric{padding:15px;min-height:128px!important}.metric strong{font-size:1.55rem}.child-overview{padding:18px}.leader-head,.mini-leader{padding-inline:16px}.rank-number{width:52px;height:52px}}</style>
