<section class="card"><h2>Activity notifications</h2><p>New searches, completed lessons and quizzes are counted since you last marked them as read.</p><p><strong>Device notification status:</strong> <span id="notificationStatus">Checking…</span></p><div class="row"><form method="post"><?=csrf_field()?><input type="hidden" name="mark_read" value="<?=intval($child['id'])?>"><button type="submit">Mark notifications read</button></form><button type="button" class="alt" id="enableNotifications">Enable and test alerts</button></div></section>
<script>
const alertButton=document.getElementById('enableNotifications'),notificationStatus=document.getElementById('notificationStatus'),liveAlert=document.getElementById('liveAlert');let alertTimer,audioContext;
const inAppAlert=(title,body)=>{document.getElementById('liveAlertTitle').textContent=title;document.getElementById('liveAlertBody').textContent=body;liveAlert.classList.add('show');clearTimeout(alertTimer);alertTimer=setTimeout(()=>liveAlert.classList.remove('show'),6500);if(navigator.vibrate)navigator.vibrate([250,100,250]);try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.frequency.value=880;gain.gain.setValueAtTime(.08,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.35);oscillator.start();oscillator.stop(audioContext.currentTime+.35);}catch(e){}};
const updatePermission=()=>{if(!('Notification'in window)){notificationStatus.textContent='Not supported by this browser';return;}notificationStatus.textContent=Notification.permission==='granted'?'Enabled ✓':Notification.permission==='denied'?'Blocked in browser/phone settings':'Permission not granted';if(Notification.permission==='granted')alertButton.textContent='Test notification';};
const notifyParent=async(title,body)=>{inAppAlert(title,body);if(!('Notification'in window)||Notification.permission!=='granted')return false;const options={body,icon:'<?=url('logo/k-transparent.png')?>',badge:'<?=url('logo/k-transparent.png')?>',tag:'parent-learning-<?=intval($child['id'])?>-'+Date.now(),renotify:true,vibrate:[250,100,250],data:{url:'<?=url('parent/dashboard.php?child='.intval($child['id']))?>'}};try{if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.ready;await registration.showNotification(title,options);}else new Notification(title,options);return true;}catch(e){try{new Notification(title,options);return true;}catch(ignored){return false;}}};
alertButton?.addEventListener('click',async()=>{if(!('Notification'in window)){inAppAlert('In-app alerts enabled','System notifications are not supported by this browser.');return;}if(Notification.permission!=='granted')await Notification.requestPermission();updatePermission();if(Notification.permission==='granted'){audioContext=new(window.AudioContext||window.webkitAudioContext)();await audioContext.resume();await notifyParent('K Education Parent Monitoring','Success! Real-time parent notifications are enabled.');}else alert('Notifications are blocked. Open this app’s Site settings → Notifications → Allow.');});
updatePermission();
let lastActivityCount=<?=intval($unread)?>;
const pollActivity=async()=>{try{const response=await fetch('activity_poll.php?child=<?=intval($child['id'])?>',{cache:'no-store',credentials:'same-origin'});if(!response.ok)return;const data=await response.json();if(data.ok&&data.total>lastActivityCount){const notice=data.notification||{title:'Learning update',body:`${data.student} completed a new activity.`};await notifyParent(notice.title,notice.body);document.getElementById('newActivity')?.remove();const badge=document.createElement('span');badge.className='badge';badge.id='newActivity';badge.textContent=data.total+' new activities';document.querySelector('.parent-head .parent-head')?.appendChild(badge);}if(data.ok)lastActivityCount=data.total;}catch(e){}}
const liveStatus=document.getElementById('liveStatus');
if('EventSource'in window){const stream=new EventSource('activity_stream.php?child=<?=intval($child['id'])?>');stream.addEventListener('open',()=>{liveStatus.innerHTML='<i></i> Live now';});stream.addEventListener('activity',async event=>{const data=JSON.parse(event.data);if(data.total>lastActivityCount){const notice=data.notification||{title:'Learning update',body:`${data.student} completed a new activity.`};await notifyParent(notice.title,notice.body);lastActivityCount=data.total;setTimeout(()=>location.reload(),1200);}else lastActivityCount=data.total;});stream.onerror=()=>{liveStatus.innerHTML='<i></i> Reconnecting';};}else{liveStatus.innerHTML='<i></i> Live polling';setInterval(pollActivity,15000);}
</script>
<?php endif;include __DIR__.'/../includes/footer.php';
